        """Returns the doctor's active appointments sorted by start time."""
        doctor_appts = [
            appt
            for appt in self._appointments.values()
            if not appt.cancelled and appt.doctor == doctor
        ]
        doctor_appts.sort(key=lambda appt: appt.start)

